const qs = $('Pick Random Question Set').first().json;
const cnt = $('Count Questions In Set').first().json;
const totalQuestion = parseInt(cnt.total_question) || 0;

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

function randomCode(len) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let s = '';
  for (let i = 0; i < len; i++) s += chars[Math.floor(Math.random() * chars.length)];
  return s;
}

const examCode = randomCode(8);
const timePerQuestion = 30; // seconds per question (default)
const durationMinutes = Math.max(1, Math.ceil((timePerQuestion * totalQuestion) / 60));
const passMark = Math.max(1, Math.ceil(totalQuestion * 0.4)); // 40% default pass mark

const now = new Date();
const scheduledStart = new Date(now.getTime() + 5 * 24 * 60 * 60 * 1000); // +5 days lead time for marketing
scheduledStart.setUTCHours(9, 0, 0, 0); // 09:00 UTC kickoff

function toMysqlDatetime(d) {
  return d.toISOString().slice(0, 19).replace('T', ' ');
}

const examName = qs.exam_name || qs.name || 'Weekly Quiz';
const examNameBn = qs.exam_name_bn || qs.name_bn || null;
const scheduledStartStr = toMysqlDatetime(scheduledStart);
const joinUrl = `https://app.questionhut.com/join-exam/${examCode}`;

const insertSql = `INSERT INTO online_exam
(exam_name, exam_name_bn, examType, status, date, duration, questionSetId, total_question, pass_mark, user_id, examCode, exam_mode, time_per_question, scheduled_start_time, completed)
VALUES
(${esc(examName)}, ${esc(examNameBn)}, 'public', 1, ${esc(scheduledStartStr)}, ${durationMinutes}, ${qs.id}, ${totalQuestion}, ${passMark}, 1, ${esc(examCode)}, 'LIVE_QUIZ', ${timePerQuestion}, ${esc(scheduledStartStr)}, 0)`;

return {
  json: {
    exam_name: examName,
    exam_code: examCode,
    duration: durationMinutes,
    pass_mark: passMark,
    total_question: totalQuestion,
    scheduled_start_time: scheduledStartStr,
    join_url: joinUrl,
    insert_sql: insertSql
  }
};

